def read_project_files() -> dict[str, str]:
    """Decode the complete project stored inside this file."""

    compressed = base64.b64decode(PROJECT_FILES)
    content = zlib.decompress(compressed).decode("utf-8")
    return json.loads(content)


def write_project(base_directory: str | Path) -> Path:
    """Create the project folder and write every stored file."""

    project_directory = Path(base_directory).expanduser().resolve() / PROJECT_NAME
    project_directory.mkdir(parents=True, exist_ok=True)

    for relative_path, content in read_project_files().items():
        target = project_directory / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")

    # Copy this generator so the recreated project can be copied again later.
    generator_copy = project_directory / "generate_project.py"
    generator_copy.write_text(Path(__file__).read_text(encoding="utf-8"), encoding="utf-8")
    return project_directory


if __name__ == "__main__":
    destination = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    output = write_project(destination)
    print(f"Created project: {output}")
    print("Review FOLDER PATH/.env, then run 'make local' from that folder.")
